import { describe, expect, it } from 'vite-plus/test';
import {
	emptyMetadata,
	inspectManualInterventions,
	parseGcode,
	safeRelativePath,
	startReason,
	validGcodeName
} from './jobs.js';
import { initialSnapshot } from './printer.js';
const encode = (text: string) => new TextEncoder().encode(text);
describe('job inspection and readiness', () => {
	it('reads Orca/Prusa and Cura comment estimates without executing commands', () => {
		const m = parseGcode(
			encode(
				'; generated by OrcaSlicer 2.4\n; filament_type = PETG\n; estimated printing time (normal mode) = 1h 3m 2s\n; layer_height = 0.2\n; total layer number = 120\n; filament used [g] = 12.4\nG28\n'
			)
		);
		expect(m).toMatchObject({
			slicer: 'OrcaSlicer 2.4',
			material: 'PETG',
			estimatedSeconds: 3782,
			layerHeight: 0.2,
			layers: 120,
			filamentGrams: 12.4
		});
		expect(parseGcode(encode(';TIME:210\nG1 X1'))).toMatchObject({ estimatedSeconds: 210 });
		expect(parseGcode(encode('G28\n'))).toEqual({
			...emptyMetadata(),
			manualInterventions: { filamentChanges: 0, pauses: 0, locations: [] }
		});
	});
	it('rejects binary and command-free files, traversal and host URLs', () => {
		expect(() => parseGcode(new Uint8Array([0xff, 0x00]))).toThrow();
		expect(() => parseGcode(encode('; only comments'))).toThrow();
		for (const name of ['../a.gcode', 'a/b.gcode', 'a\\b.gcode', 'bad\0.gcode', 'model.3mf'])
			expect(validGcodeName(name)).toBe(false);
		for (const path of [
			'../.thumbs/a.png',
			'http://private/a.png',
			'%2e%2e/a.gcode',
			'a\\b.gcode',
			'/a.gcode'
		])
			expect(safeRelativePath(path)).toBe(false);
		expect(validGcodeName('A moon bracket.gcode')).toBe(true);
		expect(safeRelativePath('parts/A moon.gcode')).toBe(true);
	});
	it('blocks a print while another is active, pending, unavailable or calibrating', () => {
		const state = initialSnapshot();
		expect(startReason(state)).toContain('current print');
		state.job.state = 'cancelled';
		expect(startReason(state)).toBeNull();
		state.actions = [
			{ id: 'action', label: 'Start', status: 'queued', createdAt: 0, message: null }
		];
		expect(startReason(state)).toContain('pending');
		state.actions = [];
		state.motion.calibration = true;
		expect(startReason(state)).toContain('calibration');
		state.motion.calibration = false;
		state.connection = 'disconnected';
		expect(startReason(state)).toContain('Reconnect');
		state.mode = 'moonraker';
		expect(startReason(state)).toContain('read-only');
	});
});

it.each(['pause', 'resume', 'cancel'] as const)(
	'rejects a stale %s aimed at a previous run of the same file',
	async (type) => {
		const { applyCommand } = await import('./printer.js');
		const previous = initialSnapshot();
		const current = initialSnapshot();
		current.job.filename = previous.job.filename;
		const expectedJob = { filename: previous.job.filename, runId: previous.job.runId ?? null };
		const command =
			type === 'cancel'
				? { type, coolBed: true, coolNozzle: true, expectedJob }
				: { type, expectedJob };
		expect(() => applyCommand(current, command)).toThrow('active job changed');
	}
);

it('counts only recognizable executable filament-change and pause commands with bounded locations', () => {
	const result = inspectManualInterventions(
		encode(
			'; M600\n(M600) G1 X1\nRESPOND MSG="M600"\nM600_OTHER\nM6000\nN23 M600 *12 ; change\n  m0600 ; change\nPAUSE\nM0\nM1\nM25\n'
		)
	);
	expect(result).toMatchObject({ filamentChanges: 2, pauses: 4 });
	expect(result.locations[0]).toEqual({ line: 6, command: 'M600' });
	expect(inspectManualInterventions(encode('M600\n'.repeat(30))).locations).toHaveLength(12);
	expect(inspectManualInterventions(encode('G1 X10\n'))).toMatchObject({
		filamentChanges: 0,
		pauses: 0
	});
	expect(() => inspectManualInterventions(new Uint8Array(20 * 1024 * 1024 + 1))).toThrow('limit');
	expect(() => inspectManualInterventions(encode('M600\0'))).toThrow('Binary');
});

it('handles long malformed comment prefixes without treating quoted or commented commands as changes', () => {
	expect(inspectManualInterventions(encode('('.repeat(100_000) + '\nG1 X1\n'))).toMatchObject({
		filamentChanges: 0,
		pauses: 0
	});
	expect(() => inspectManualInterventions(encode('{"result":"M600"}'))).toThrow('commands');
});
